def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    from collections import deque

    MOD = 1_000_000_007

    if n == 0:
        return 1
    if not banned:
        return pow(len(alphabet), n, MOD)

    char_index = {c: i for i, c in enumerate(alphabet)}
    width = len(alphabet)

    transitions = [[-1] * width]
    failure = [0]
    forbidden = [False]

    for word in banned:
        state = 0
        for char in word:
            c = char_index[char]
            if transitions[state][c] == -1:
                transitions[state][c] = len(transitions)
                transitions.append([-1] * width)
                failure.append(0)
                forbidden.append(False)
            state = transitions[state][c]
        forbidden[state] = True

    queue = deque()
    for c in range(width):
        child = transitions[0][c]
        if child == -1:
            transitions[0][c] = 0
        else:
            queue.append(child)

    while queue:
        state = queue.popleft()
        fallback = failure[state]
        forbidden[state] |= forbidden[fallback]

        for c in range(width):
            child = transitions[state][c]
            if child == -1:
                transitions[state][c] = transitions[fallback][c]
            else:
                failure[child] = transitions[fallback][c]
                queue.append(child)

    safe_states = [
        state for state in range(len(transitions))
        if not forbidden[state]
    ]
    indices = {state: i for i, state in enumerate(safe_states)}
    size = len(safe_states)

    matrix = [[0] * size for _ in range(size)]
    for i, state in enumerate(safe_states):
        for target in transitions[state]:
            if not forbidden[target]:
                matrix[i][indices[target]] += 1

    def square(matrix):
        result = []
        for source_row in matrix:
            row = [0] * size
            for k, coefficient in enumerate(source_row):
                if coefficient:
                    for j, value in enumerate(matrix[k]):
                        if value:
                            row[j] += coefficient * value
            result.append([value % MOD for value in row])
        return result

    counts = [0] * size
    counts[indices[0]] = 1

    while n:
        if n & 1:
            next_counts = [0] * size
            for i, count in enumerate(counts):
                if count:
                    for j, value in enumerate(matrix[i]):
                        if value:
                            next_counts[j] += count * value
            counts = [value % MOD for value in next_counts]

        n >>= 1
        if n:
            matrix = square(matrix)

    return sum(counts) % MOD
